{
  "schema": "craft-native-command-snapshot/v1",
  "pluginId": "effectcraft",
  "runtimeSha256": "74d44fc90018ac381dc4516edff939ab26eb6d900ae5c3f49d1eba5ac14105fe",
  "mode": "headless-empty",
  "scope": "registered commands and empty-session state only; no command execution acceptance",
  "tools": [
    {
      "description": "List engine commands: id, label, menu path, shortcut, `params` doc (e.g. `{name?, width?, height?, frameRate?, duration? (s)}`) and whether it can run now (`why` if not). Every menu item, shortcut and panel gesture maps to one of these ids; run them with execute_command. Narrow with `filter` (e.g. `layer.new`, `keys`, `effect`).",
      "inputSchema": {
        "properties": {
          "enabled_only": {
            "description": "Only commands that can run right now.",
            "type": "boolean"
          },
          "filter": {
            "description": "Only commands whose id or label contains this text (case-insensitive).",
            "type": "string"
          },
          "schemas": {
            "description": "Also return each command's parameter JSON Schema (`schema`).",
            "type": "boolean"
          }
        },
        "required": [],
        "type": "object"
      },
      "name": "list_commands"
    },
    {
      "description": "One command in full: id, label, menu path, shortcut, the `params` doc, a JSON Schema of its parameters (`schema`: properties, required, additionalProperties) and whether it can run now (`why` if not). Use before execute_command when unsure of the parameters; execute_command rejects unknown keys.",
      "inputSchema": {
        "properties": {
          "command": {
            "description": "Command id, e.g. `layer.newText`.",
            "type": "string"
          }
        },
        "required": [
          "command"
        ],
        "type": "object"
      },
      "name": "describe_command"
    },
    {
      "description": "Run any engine command by id with JSON params; edits are undoable. Examples: comp.new {\"name\":\"Main\",\"width\":1920,\"height\":1080,\"frameRate\":30,\"duration\":5}; layer.newText {\"text\":\"Hello\",\"size\":120,\"fill\":\"#ffffff\"} (returns {\"layer\":id}); layer.newSolid {\"color\":\"#3366ff\"}; layer.newShape; effect.apply {\"layer\":3,\"effect\":\"Gaussian Blur\"}; time.set {\"time\":2.5}; layer.select {\"layers\":[3]}. Layers are referenced by id, \"#n\" or name; times are seconds.",
      "inputSchema": {
        "properties": {
          "command": {
            "description": "Command id, e.g. `comp.new`, `layer.newText`, `effect.apply` (see list_commands).",
            "type": "string"
          },
          "params": {
            "additionalProperties": true,
            "description": "Command parameters as documented by list_commands.",
            "type": "object"
          }
        },
        "required": [
          "command"
        ],
        "type": "object"
      },
      "name": "execute_command"
    },
    {
      "description": "Run JavaScript with an After Effects-style scripting object model (app, app.project, items.addComp, comp.layers.addSolid/addText/addShape/addNull/addCamera/addLight, layer.property(\"ADBE Transform Group\").property(\"ADBE Position\").setValueAtTime(t, v), Effects.addProperty(\"ADBE Gaussian Blur 2\"), expressions, markers, renderQueue…). Every edit is an undoable engine command; app.beginUndoGroup/endUndoGroup make one undo step. Returns {ok, result (last expression value), output (writeLn/$.writeln/alert text), error: {message, line, column} | null}. File access is limited to the project folder unless the user allows scripts to write files.",
      "inputSchema": {
        "properties": {
          "code": {
            "description": "JavaScript source, e.g. `var c = app.project.items.addComp(\"Main\", 1920, 1080, 1, 5, 30); c.layers.addText(\"Hi\"); c.numLayers`.",
            "type": "string"
          },
          "name": {
            "description": "Script name used in error messages (default `script`).",
            "type": "string"
          }
        },
        "required": [
          "code"
        ],
        "type": "object"
      },
      "name": "run_script"
    },
    {
      "description": "Project overview: file path, dirty flag, bit depth, every item (id, name, type Composition/Footage/Solid/Folder, size, duration, layer count), the active comp id, current time (s), selected layers and the undo stack.",
      "inputSchema": {
        "properties": {},
        "required": [],
        "type": "object"
      },
      "name": "get_project"
    },
    {
      "description": "A composition: id, name, size, frame rate, duration, work area, background and its layers top to bottom (id, index, name, type, in/out/start seconds, blend mode, parent, track matte, switches). Layer ids feed get_layer, get_property/set_property and commands.",
      "inputSchema": {
        "properties": {
          "comp": {
            "description": "Composition item id or name; omit for the active comp.",
            "type": [
              "integer",
              "string"
            ]
          }
        },
        "required": [],
        "type": "object"
      },
      "name": "get_comp"
    },
    {
      "description": "A layer's property tree (transform, masks, effects, text, shape contents, ...): every node has a `path` usable with get_property/set_property/add_keyframe, plus uid, match id, name, type, value at `time`, keyframes and expression. `flat: true` returns just a list of {path, type, value, keys, expression} (compact).",
      "inputSchema": {
        "properties": {
          "comp": {
            "description": "Composition item id or name; omit for the active comp.",
            "type": [
              "integer",
              "string"
            ]
          },
          "depth": {
            "description": "Group depth to expand (default all).",
            "type": "integer"
          },
          "flat": {
            "description": "Return a flat list of properties instead of the tree.",
            "type": "boolean"
          },
          "layer": {
            "description": "Layer id (from get_comp), \"#n\" (1-based index from the top) or layer name.",
            "type": [
              "integer",
              "string"
            ]
          },
          "time": {
            "description": "Comp time in seconds for values (default: current time).",
            "type": "number"
          }
        },
        "required": [
          "layer"
        ],
        "type": "object"
      },
      "name": "get_layer"
    },
    {
      "description": "Read one property: type, value at `time` (comp seconds; default the current time), whether it is animated, its keyframes (time, value, in/out interpolation) and expression.",
      "inputSchema": {
        "properties": {
          "comp": {
            "description": "Composition item id or name; omit for the active comp.",
            "type": [
              "integer",
              "string"
            ]
          },
          "layer": {
            "description": "Layer id (from get_comp), \"#n\" (1-based index from the top) or layer name.",
            "type": [
              "integer",
              "string"
            ]
          },
          "path": {
            "description": "Property path from get_layer: match ids joined by `/`, `#n` for the nth child, or `@uid`. E.g. `transform/position`, `transform/opacity`, `transform/scale`, `transform/rotation`, `effects/#1/blurriness`, `masks/#1/feather`, `@57`.",
            "type": "string"
          },
          "time": {
            "description": "Comp time in seconds.",
            "type": "number"
          }
        },
        "required": [
          "layer",
          "path"
        ],
        "type": "object"
      },
      "name": "get_property"
    },
    {
      "description": "Set a property. Without `time`: sets the static value (or a key at the current time if already animated). With `time`: adds/replaces a keyframe there, turning the stopwatch on. `expression` sets an After Effects-style JS expression (\"\" removes it). Returns the property as get_property does. Examples: {\"layer\":3,\"path\":\"transform/opacity\",\"value\":50}; {\"layer\":\"Title\",\"path\":\"transform/position\",\"value\":[200,540],\"time\":0}; {\"layer\":3,\"path\":\"transform/rotation\",\"expression\":\"time*90\"}.",
      "inputSchema": {
        "properties": {
          "comp": {
            "description": "Composition item id or name; omit for the active comp.",
            "type": [
              "integer",
              "string"
            ]
          },
          "expression": {
            "description": "Expression text; empty string removes the expression.",
            "type": "string"
          },
          "layer": {
            "description": "Layer id (from get_comp), \"#n\" (1-based index from the top) or layer name.",
            "type": [
              "integer",
              "string"
            ]
          },
          "path": {
            "description": "Property path from get_layer: match ids joined by `/`, `#n` for the nth child, or `@uid`. E.g. `transform/position`, `transform/opacity`, `transform/scale`, `transform/rotation`, `effects/#1/blurriness`, `masks/#1/feather`, `@57`.",
            "type": "string"
          },
          "time": {
            "description": "Keyframe time in seconds (layer time; equals comp time unless the layer is offset/stretched).",
            "type": "number"
          },
          "value": {
            "description": "Number for 1-D properties (50), array for vectors ([960,540]), \"#rrggbb\" or [r,g,b,a] (0-1) for colours, bool for checkboxes, string for text/menus."
          }
        },
        "required": [
          "layer",
          "path"
        ],
        "type": "object"
      },
      "name": "set_property"
    },
    {
      "description": "Add keyframes to a property (turns the stopwatch on): one with `time` (+ optional `value`, default the current value) or many with `keys: [{time, value}]`, then optionally set their `interpolation`: linear, bezier, hold, easyEase, easyEaseIn, easyEaseOut. Example: {\"layer\":1,\"path\":\"transform/position\",\"keys\":[{\"time\":0,\"value\":[0,540]},{\"time\":2,\"value\":[1920,540]}],\"interpolation\":\"easyEase\"}.",
      "inputSchema": {
        "properties": {
          "comp": {
            "description": "Composition item id or name; omit for the active comp.",
            "type": [
              "integer",
              "string"
            ]
          },
          "interpolation": {
            "enum": [
              "linear",
              "bezier",
              "hold",
              "easyEase",
              "easyEaseIn",
              "easyEaseOut"
            ],
            "type": "string"
          },
          "keys": {
            "description": "Several keys at once.",
            "items": {
              "properties": {
                "time": {
                  "type": "number"
                },
                "value": {
                  "description": "Number for 1-D properties (50), array for vectors ([960,540]), \"#rrggbb\" or [r,g,b,a] (0-1) for colours, bool for checkboxes, string for text/menus."
                }
              },
              "required": [
                "time"
              ],
              "type": "object"
            },
            "type": "array"
          },
          "layer": {
            "description": "Layer id (from get_comp), \"#n\" (1-based index from the top) or layer name.",
            "type": [
              "integer",
              "string"
            ]
          },
          "path": {
            "description": "Property path from get_layer: match ids joined by `/`, `#n` for the nth child, or `@uid`. E.g. `transform/position`, `transform/opacity`, `transform/scale`, `transform/rotation`, `effects/#1/blurriness`, `masks/#1/feather`, `@57`.",
            "type": "string"
          },
          "time": {
            "description": "Key time in seconds (layer time).",
            "type": "number"
          },
          "value": {
            "description": "Number for 1-D properties (50), array for vectors ([960,540]), \"#rrggbb\" or [r,g,b,a] (0-1) for colours, bool for checkboxes, string for text/menus."
          }
        },
        "required": [
          "layer",
          "path"
        ],
        "type": "object"
      },
      "name": "add_keyframe"
    },
    {
      "description": "Apply an effect to a layer and optionally set its parameters in one undoable call. `effect` is an id (`ec.blur.gaussian`) or After Effects name (`Gaussian Blur`; see list_effects); `values` maps parameter ids to values, e.g. {\"blurriness\": 12}. Returns the instance `path` (`effects/#n`, for set_property / add_keyframe) and its parameters with their paths and current values.",
      "inputSchema": {
        "properties": {
          "comp": {
            "description": "Composition item id or name; omit for the active comp.",
            "type": [
              "integer",
              "string"
            ]
          },
          "effect": {
            "description": "Effect id or name, e.g. `Gaussian Blur`, `Glow`, `Curves`, `ec.color.levels`.",
            "type": "string"
          },
          "layer": {
            "description": "Layer id (from get_comp), \"#n\" (1-based index from the top) or layer name.",
            "type": [
              "integer",
              "string"
            ]
          },
          "values": {
            "additionalProperties": true,
            "description": "Parameter id -> value (ids are in the returned `params` paths), e.g. {\"blurriness\": 12}.",
            "type": "object"
          }
        },
        "required": [
          "layer",
          "effect"
        ],
        "type": "object"
      },
      "name": "add_effect"
    },
    {
      "description": "The effect registry: id, After Effects name, category, GPU and 32-bpc support. Narrow with `filter` (id, name or category text). Apply with add_effect.",
      "inputSchema": {
        "properties": {
          "filter": {
            "description": "Only effects whose id, name or category contains this text.",
            "type": "string"
          }
        },
        "required": [],
        "type": "object"
      },
      "name": "list_effects"
    },
    {
