{
  "schema": "craft-native-command-snapshot/v1",
  "pluginId": "vectorcraft",
  "runtimeSha256": "ac47d32f34b8910dd559cff59d64cafaaade066227714359d1821cb2b0e59d1b",
  "mode": "headless-empty",
  "scope": "registered commands and empty-session state only; no command execution acceptance",
  "tools": [
    {
      "annotations": {
        "openWorldHint": false,
        "readOnlyHint": true,
        "title": "List commands"
      },
      "description": "List VectorCraft commands (id, label, menu path, shortcut, parameter description, enabled state). Every editing action is a command; run any of them with run_command. Coordinates are points in document space, y down, origin at the first artboard's top-left.",
      "inputSchema": {
        "properties": {
          "enabledOnly": {
            "description": "Only commands that can run right now",
            "type": "boolean"
          },
          "filter": {
            "description": "Case-insensitive substring matched against id, label and menu path (e.g. \"align\", \"Object\")",
            "type": "string"
          }
        },
        "type": "object"
      },
      "name": "list_commands",
      "title": "List commands"
    },
    {
      "annotations": {
        "openWorldHint": false,
        "readOnlyHint": false,
        "title": "Run command"
      },
      "description": "Execute any VectorCraft command by id with JSON params (see list_commands for ids and params). Examples: {\"command\":\"object.group\"}, {\"command\":\"object.align\",\"params\":{\"align\":\"left\"}}, {\"command\":\"file.new\",\"params\":{\"width\":800,\"height\":600}}. Returns the command's result (e.g. {id} for creation commands).",
      "inputSchema": {
        "properties": {
          "command": {
            "description": "Command id, e.g. shape.rectangle, object.group, paint.setFill",
            "type": "string"
          },
          "params": {
            "description": "Command parameters",
            "type": "object"
          }
        },
        "required": [
          "command"
        ],
        "type": "object"
      },
      "name": "run_command",
      "title": "Run command"
    },
    {
      "annotations": {
        "openWorldHint": false,
        "readOnlyHint": true,
        "title": "Inspect document"
      },
      "description": "Summary of the active document: artboards, layer tree (ids, names, kinds, bounds, fill/stroke), selection, undo history, current tool and default paint.",
      "inputSchema": {
        "properties": {},
        "type": "object"
      },
      "name": "inspect_document",
      "title": "Inspect document"
    },
    {
      "annotations": {
        "openWorldHint": false,
        "readOnlyHint": true,
        "title": "Inspect UI"
      },
      "description": "UI state of the running desktop app: tool and options, panels, dialogs, view (zoom/center), window, documents, perf. Desktop app only.",
